// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public {
        c = new Owned();
        // owner defaults to address(0); become that owner to exercise the guarded paths
        vm.prank(address(0));
        c.owned();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        // General rule: after transferOwnership(new), the public owner is exactly new.
        assertTrue(c.owner() == newOwner);
    }
}
